// Writes src/generated/assets.ts: static imports of the shared-assets files the card draws
// (wrangler's Text/Data rules turn them into modules), so they stay in sync with the folder.
import { mkdirSync, readdirSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
const assets = fileURLToPath(new URL('../../shared-assets/', import.meta.url));
const ribbons = readdirSync(`${assets}ribbons`)
	.filter((file) => /^ribbon-\d+\.svg$/.test(file))
	.sort();
const lines = [
	'// Generated by scripts/generate-assets.mjs; do not edit.',
	"import medal from '../../../shared-assets/supporter/medal.svg';",
	"import us from '../../../shared-assets/factions/us.png';",
	"import wm from '../../../shared-assets/factions/wm.png';",
	"import cw from '../../../shared-assets/factions/cw.png';",
	"import pe from '../../../shared-assets/factions/pe.png';",
	...ribbons.map((file, i) => `import r${i} from '../../../shared-assets/ribbons/${file}';`),
	'',
	'export const MEDAL_SVG: string = medal;',
	'/** Faction flag PNGs by race id. */',
	'export const FLAGS: Record<number, ArrayBuffer> = { 0: us, 1: wm, 2: cw, 3: pe };',
	'/** Ribbon SVGs by key (`ribbon-042`). */',
	'export const RIBBONS: Record<string, string> = {',
	ribbons.map((file, i) => `\t'${file.replace(/\.svg$/, '')}': r${i}`).join(',\n'),
	'};',
	''
];
mkdirSync(`${root}src/generated`, { recursive: true });
writeFileSync(`${root}src/generated/assets.ts`, lines.join('\n'));
console.log(`card-worker: ${ribbons.length} ribbons`);
